select date_format(start_date, 'yyyy-MM') as start_month, status, case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end as start_cohort, max(start_date) as latest_start_date, max(monthly_fee) - min(monthly_fee) as monthly_fee_range from subscriptions where customer_id is not null group by start_month, status, start_cohort having monthly_fee_range < 65 order by start_month asc, status asc, start_cohort asc limit 10
